style.css:
/* --- Universal Pink & Pretty Theme --- */

/* Background of page */
body {
    background-color: #ffe4f1 !important; /* soft pink */
    color: #6a1b9a !important; /* deep purple text */
    font-family: 'Comic Sans MS', 'Segoe UI', sans-serif !important; /* playful font */
}

/* Links */
a {
    color: #ff69b4 !important; /* hot pink links */
    text-decoration: underline dotted !important;
}

/* Buttons */
button, input[type="button"], input[type="submit"] {
    background-color: #ffb6c1 !important; /* light pink buttons */
    border: 2px solid #ff69b4 !important; /* darker pink border */
    border-radius: 12px !important; /* rounded edges */
    color: #6a1b9a !important; /* purple text */
    font-weight: bold;
    transition: all 0.3s ease;
}

button:hover, input[type="button"]:hover, input[type="submit"]:hover {
    background-color: #ff69b4 !important;
    color: #fff !important;
    transform: scale(1.05);
}

/* Inputs and text areas */
input, textarea {
    border: 2px solid #ff69b4 !important;
    border-radius: 8px !important;
    background-color: #fff0f5 !important;
    color: #6a1b9a !important;
}

/* Optional: make images have a cute border */
img {
    border-radius: 12px;
    border: 2px solid #ffb6c1;
}
